import{_ as t,a}from"./chunks/built-with-blockly-badge-black.BLndjqRJ.js";import{_ as o,o as n,c as r,a3 as s}from"./chunks/framework.BlfGB29P.js";const i="/assets/blocks-for-ha/ui/en.png",k=JSON.parse('{"title":"Blocks for HA","description":"Create native Home Assistant automations with visual Blocks.","frontmatter":{"title":"Blocks for HA","description":"Create native Home Assistant automations with visual Blocks."},"headers":[],"relativePath":"en/projects/blocks-for-ha/index.md","filePath":"en/projects/blocks-for-ha/index.md","lastUpdated":1792861021000}'),d={name:"en/projects/blocks-for-ha/index.md"};function l(c,e,p,g,h,u){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="blocks-for-ha" tabindex="-1">Blocks for HA <a class="header-anchor" href="#blocks-for-ha" aria-label="Permalink to &quot;Blocks for HA&quot;">​</a></h1><p>New in <strong>0.1.66</strong>: unnecessary sample text removed across all categories, including MQTT, objects, lists, conversions and fallbacks. Assist responses and literal Jinja text start empty with single-line inputs. Separators, valid JSON structures and technical settings remain, as do existing project values.</p><p>New in <strong>0.1.65</strong>: single-line text block without an extra hint row, empty new text fields and no preconnected Hello block in Create text from. Existing text is retained.</p><p>New in <strong>0.1.64</strong>: purpose-specific Templates for text, time periods, value changes and typed if/else results. Free Jinja code appears once in Templates. App/automation controls use two rows like ioBroker. Complete DE/EN/FR. <a href="./system-template">Guide and images</a>.</p><p>New in <strong>0.1.63</strong>: direct typed Template value sockets like ioBroker&#39;s Write file block, automatically adding another input. No gears on Template blocks. Older chains migrate on load. <a href="./system-template">Guide</a>.</p><p>New in <strong>0.1.62</strong>: entity ID and shared entity values in System, read-once snapshot, app and automation controls, and a visual Template builder. Connect text, math, variables and System values; add number formatting, fallback, newlines and conditional output. Right-click for Jinja and HA preview. DE/EN/FR. <a href="./system-template">Guide</a>.</p><p>New in <strong>0.1.61</strong>: separate <strong>and / or / not</strong> blocks. Add, remove and reorder individual optional HA fields through the gear. Required fields and imported values remain intact. DE/EN/FR. <a href="./advanced">Reviewed blocks and usage</a>.</p><p>New in <strong>0.1.60</strong>: <strong>Schedule</strong> with Wizard/Simple/CRON popup, component tabs and optional seconds, weekdays, trigger data and sun offsets. Extended native HA triggers directly in <strong>Triggers</strong>. DE/EN/FR. <a href="./time">ioBroker comparison and limits</a>.</p><p>New in <strong>0.1.59</strong>: ioBroker-style labels and gear builders, <strong>Comment</strong> in System with YAML comments, and <strong>MQTT message</strong> in Messages without an instance selector. Labels and block images in DE/EN/FR. <a href="./blocks">Details and images</a>.</p><h2 id="empty-start-since-0-1-52" tabindex="-1">Empty start since 0.1.52 <a class="header-anchor" href="#empty-start-since-0-1-52" aria-label="Permalink to &quot;Empty start since 0.1.52&quot;">​</a></h2><p>Since <strong>0.1.54</strong>, <strong>New automation</strong> offers <strong>Save and start new</strong>, <strong>Start new without saving</strong> or <strong>Cancel</strong>. Before clearing, the backup downloads as <code>.blocks.json</code>, including blocks, automation metadata and pasted YAML. Restore it with <strong>Open project</strong>. Cancel or Escape preserves the current work. Starting new resets blocks, undo history, name, description and inputs. Language, appearance, HA connection and installed block packages remain available.</p><p>Without a saved project, the editor starts completely empty. Drag <strong>Automation</strong> from <strong>System</strong> onto the workspace or import YAML. Importing into an empty editor does not require “Completely replace current automation”. Examples open only through <strong>Load example</strong>.</p><p>Saved projects resume on the next start. Empty projects stay empty after reload or language changes. If the saved browser project cannot be loaded, an empty editor opens with a notice, without an example.</p><p>New in <strong>0.1.47</strong>: <a href="./blockly-audit">Action functions with parameters and conditional return values</a>. The complete catalogue now supports 166 block types.</p><p>New in <strong>0.1.46</strong>: <strong>Language → System / DE / EN / FR</strong> now applies to the entire interface, dialogs, status, confirmations and validation messages. User names, entity data, package labels and YAML/Jinja are not translated automatically.</p><p><img src="'+i+`" alt="English interface; test data and user names retain their original language"></p><p>New in <strong>0.1.45</strong>: four duplicate toolbox entries removed. Number only under Mathematics, text under Text, colour under Colour, expandable AND/OR/NOT under Logic. Values contains percentage; existing projects remain compatible.</p><p>New in <strong>0.1.44</strong>: searchable action and target selection, five target types, multiple targets and manual Jinja entry. <a href="./entities">Usage and limits</a>.</p><p>New in <strong>0.1.42</strong>: three compact, equally sized YAML import buttons, with two-line labels when needed. <strong>Eingabefeld leeren</strong> on the right clears the pasted text and import error. The current automation and replacement checkbox remain unchanged.</p><p>New in <strong>0.1.41</strong>: 15 nested Jinja block types, 163 types in total. Edit entities, filters, comparisons, calculations and simple if/else/for templates. Exact originals remain until editing; unsupported templates remain original blocks. <a href="./advanced#jinja-experimental">Decomposition and limits</a>.</p><p>Since <strong>0.1.40</strong>, all themes use <strong>16 px block text</strong>. The block menu stays at <strong>100%</strong>: fitting, mouse wheel and zoom controls affect only the workspace. Initial zoom 100%, fitting 85–120%, manual zoom 50–240%. Large automations remain scrollable; fitting never shrinks below 85% to preserve readability. Verified at Full HD, 2560 px and HiDPI.</p><p>New in <strong>0.1.39</strong>: 148 block types, extended HA triggers/conditions, targets/variables/options, waits, parallel branches, action groups and <strong>Jinja (experimental)</strong> with recognition and preserved originals. <a href="./advanced">Guide, limits and sources</a>.</p><p><strong>Language → System language / DE / EN / FR</strong> follows preferred browser languages, with English as the fallback for unsupported languages. App labels, dropdowns, help, categories and dialogs are translated. Switching saves the valid project and reloads the editor; incomplete blocks or unavailable storage keep the current view. Technical IDs, variable names, user text, templates and YAML are unchanged. Packages retain their authors’ language. <a href="/fr/projects/blocks-for-ha/">French documentation</a>; the catalog uses separate DE/EN/FR block images.</p><p>New in <strong>0.1.18</strong>: <a href="./custom-blocks">Custom block/template editor</a> in a 95% dialog, custom category, multiple blocks per package, copyable JSON and ZIP import/export. <a href="./catalog/">Block-package catalog</a>.</p><p>New in <strong>0.1.17</strong>: Load entities from HA and search existing block fields by name/ID. Light/script/helper filters, manual IDs offline and server-side credentials. <a href="./entities">Usage, image and limits</a>.</p><p>New in <strong>0.1.16</strong>: UGSo Standard/Dark/Modern/Tritanopia selector and zoom-to-fit control. Choice saved locally; own blocks follow palettes. <a href="./themes">Usage, images and upstream sources</a>. Still 111 block types.</p><p><strong>Version 0.1.47 · experimental HA app.</strong> Visual Blocks generate native Home Assistant automation YAML. Home Assistant runs the automation. Actions and targets are selectable from read-only HA catalogues.</p><p>Since <strong>0.1.25</strong>, select <strong>YAML → Code importieren</strong>, paste YAML and click <strong>Importieren</strong> instead of Save. Without the checkbox, triggers, conditions and actions are added; the current name, settings and block shapes are preserved. Conditions are combined with AND; additional triggers may start more runs. To replace everything, select <strong>Aktuelle Automation vollständig ersetzen</strong> and confirm. One supported automation as an object or single-item list is accepted, up to 1 MB. Invalid code or cancellation leaves the current blocks unchanged. Switching modes retains pasted text for this page session; successful import returns to output. Adding requires a valid current automation; complete replacement also works with incomplete blocks. File import through <strong>Öffnen</strong> remains available.</p><p>Blocks use classic Blockly puzzle shapes (Geras) with 16 px text. The menu stays at 100% independently of editor zoom. Workspace fitting uses 85–120%; large automations remain scrollable. <a href="./themes">Themes, zoom and readability</a>.</p><h2 id="block-catalog-and-original-plugins" tabindex="-1">Block catalog and original plugins <a class="header-anchor" href="#block-catalog-and-original-plugins" aria-label="Permalink to &quot;Block catalog and original plugins&quot;">​</a></h2><p>New in <strong>0.1.13</strong>: 18 blocks for <strong>timeouts, objects, logic, loops and lists</strong>. Native HA delays with units/runtime values, wait until with timeout, stop this run, repeats, dictionary access/reassignment, case selection, range comparison, fallback and lists. <a href="./flow">ioBroker / original Blockly / UGSo mapping and limitations</a>.</p><p>New in <strong>0.1.12</strong>: <strong>Conversion</strong> with nine blocks for number, Boolean, string, type, datetime, date formatting/components, duration and JSON. Dynamic format fields and a JSON pretty-print checkbox. JSONata remains a planned extension. <a href="./conversion">Guide and ioBroker comparison</a>.</p><p>New in <strong>0.1.11</strong>: seven <strong>Date and time</strong> blocks: clock comparisons, overnight periods, datetimes, calendar starts, next sun events, time calculations and formatting. <a href="./time">Guide and ioBroker comparison</a>.</p><p>New in <strong>0.1.10</strong>: <strong>Change variable by …</strong> in the variables menu, with default step <code>1</code>, negative and fractional steps. <a href="./blocks#increment-and-decrement-added-in-0-1-10">Image, example and prerequisites</a>.</p><p>New in <strong>0.1.9</strong>: <strong>Logik</strong> category with comparison, compact AND/OR, NOT, true/false, null and conditional value selection. Variables now accept Boolean and null too. <a href="./blocks#logic-blocks-added-in-0-1-9">Six new blocks with images and example</a>.</p><p>The <a href="./blocks">catalog of all 163 blocks</a> shows an image and description for each block. The original-plugin table links directly to upstream sources.</p><p>New in <strong>0.1.8</strong>: <strong>Variablen → Variable erstellen …</strong>, Set/Read variable blocks and a <strong>Templates</strong> category with dedicated value and condition blocks. Variables generate native HA <code>variables</code> actions; reads produce <code>{{ name }}</code>. Jinja is evaluated in HA. <a href="./blocks#using-variables-and-templates">Usage, example and import limits</a>.</p><p>New in 0.1.7: <strong>search at the bottom of the menu</strong>, multiline text, percentage slider, colour/light action, today’s date and dependent helper dropdowns. The gear adds or removes the last input or else-if branch; <strong>S</strong> toggles else. Removing inputs detaches blocks without deleting them. The gear remains for reordering.</p><p>The date comparison includes the year and uses HA’s <code>now().strftime(&#39;%Y-%m-%d&#39;)</code>, evaluated in HA’s time zone. It is a condition, not a trigger. Import maps this shape to the date block and other template conditions to the general template block. The light action generates RGB colour and percentage brightness. Timers use their configured duration; additional parameters stay in the generic HA action. Actual device capabilities must be checked in HA.</p><p>Our original UGSo house/puzzle icon is used by the UI, browser and HA app. Ten original plugins are bundled locally. Colour blending and random colours are implemented since 0.1.15; automatic growing connections and live action selection remain pending. Text joining and list editing are implemented.</p><h2 id="install-from-the-ha-app-store" tabindex="-1">Install from the HA app store <a class="header-anchor" href="#install-from-the-ha-app-store" aria-label="Permalink to &quot;Install from the HA app store&quot;">​</a></h2><p>Add or refresh <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> in the app store. Install <strong>Blocks for HA</strong>, start it and select <strong>Open Web UI</strong>. The app supports amd64 and aarch64 and serves the editor through HA ingress. No additional token is needed to open it. It reads HA entities through the Supervisor and does not write HA system files.</p><h2 id="start-and-files" tabindex="-1">Start and files <a class="header-anchor" href="#start-and-files" aria-label="Permalink to &quot;Start and files&quot;">​</a></h2><p>Code lives beside Grafik Visual Studio in the <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/blocks_for_ha" target="_blank" rel="noreferrer">shared repository</a>. In <code>blocks_for_ha</code>, using Node.js 22.12 or newer:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Editor: <code>http://127.0.0.1:4180/</code>. Preview, copy, download and reopen supported YAML as Blocks. Files must contain one automation object or a list with one entry. Unsupported structures are rejected. JSON projects also retain block positions; the browser persists the latest project locally.</p><h2 id="iobroker-our-blocks-existing-features" tabindex="-1">ioBroker / our Blocks: existing features <a class="header-anchor" href="#iobroker-our-blocks-existing-features" aria-label="Permalink to &quot;ioBroker / our Blocks: existing features&quot;">​</a></h2><p>111 block types including the automation root; variables, templates, date/time and conversion are described in the catalog:</p><table tabindex="0"><thead><tr><th>ioBroker concept</th><th>Blocks for HA</th><th>HA output</th></tr></thead><tbody><tr><td>Script container</td><td>Automation</td><td><code>triggers</code>, <code>conditions</code>, <code>actions</code></td></tr><tr><td>State trigger</td><td>State reached</td><td><code>trigger: state</code></td></tr><tr><td>Numeric trigger check</td><td>Above/below threshold crossing</td><td><code>trigger: numeric_state</code></td></tr><tr><td>Schedule</td><td>Time</td><td><code>trigger: time</code></td></tr><tr><td>Astro</td><td>Sunrise/sunset</td><td><code>trigger: sun</code></td></tr><tr><td>System start, different lifecycle</td><td>HA starts</td><td><code>trigger: homeassistant</code></td></tr><tr><td>State comparison</td><td>State is</td><td><code>condition: state</code></td></tr><tr><td>Numeric comparison</td><td>Number above/below</td><td><code>condition: numeric_state</code></td></tr><tr><td>AND/OR/NOT</td><td>All/at least one/none of the conditions</td><td><code>and</code>, <code>or</code>, <code>not</code></td></tr><tr><td>Control/toggle</td><td>On/off/toggle</td><td>Appropriate entity-domain action</td></tr><tr><td>Adapter action</td><td>Generic HA action</td><td><code>action</code>, optional entity target and JSON data</td></tr><tr><td>Pause</td><td>Wait seconds</td><td><code>delay</code></td></tr><tr><td>If/else if/else</td><td>Extensible if block</td><td><code>if</code> or <code>choose</code></td></tr><tr><td>Number</td><td>Number value block, also used as a shadow default</td><td>Constant threshold or delay</td></tr><tr><td>Text</td><td>Text value block with shadow</td><td>Log message</td></tr><tr><td>Percentage</td><td>Slider value 0–100</td><td>Number constant</td></tr><tr><td>Colour</td><td>Colour value</td><td>Colour constant</td></tr><tr><td>Light colour</td><td>Light with colour/brightness</td><td><code>rgb_color</code>, <code>brightness_pct</code></td></tr><tr><td>Date</td><td>Today equals/on-or-after/on-or-before</td><td>HA template condition</td></tr><tr><td>Control helper</td><td>Dependent action dropdown</td><td>Switch/counter/timer</td></tr><tr><td>Debug output</td><td>Log with severity</td><td><code>system_log.write</code></td></tr><tr><td>Control script</td><td>Start/stop/call and wait</td><td><code>script.turn_on</code>, <code>script.turn_off</code> or direct call</td></tr><tr><td>Update state, different semantics</td><td>Refresh entity</td><td><code>homeassistant.update_entity</code></td></tr></tbody></table><p>Name, description, ID and <code>single</code>, <code>restart</code>, <code>queued</code>, <code>parallel</code> modes are available. Queued/parallel support a maximum count. Three examples cover light, battery and evening light.</p><h2 id="system-blocks-added-in-version-0-1-6" tabindex="-1">System blocks added in version 0.1.6 <a class="header-anchor" href="#system-blocks-added-in-version-0-1-6" aria-label="Permalink to &quot;System blocks added in version 0.1.6&quot;">​</a></h2><p>The <strong>System</strong> category contains three new action blocks. <strong>Values</strong> also includes a green <strong>Text</strong> block with a String output for the log message input. Numbers and conditions cannot connect to this input.</p><table tabindex="0"><thead><tr><th>ioBroker</th><th>Our block</th><th>Controls and HA behavior</th></tr></thead><tbody><tr><td>Debug output</td><td>Log</td><td>Editable text shadow or text block; Info, Warning, Error, Debug or Critical dropdown. Generates <code>system_log.write</code>.</td></tr><tr><td>Control script</td><td>HA script</td><td>Enter script ID; choose start without waiting, stop, or call and wait.</td></tr><tr><td>Update state</td><td>Refresh entity</td><td>Requests a refresh through <code>homeassistant.update_entity</code>. Does not set state and has no ioBroker <code>ack</code> semantics.</td></tr><tr><td>Text</td><td>Text value block</td><td>Editable log message, retained in projects and YAML.</td></tr></tbody></table><p><strong>Start without waiting</strong> generates <code>script.turn_on</code> and lets the automation continue. <strong>Stop</strong> generates <code>script.turn_off</code>. <strong>Call and wait</strong> generates a direct <code>script.name</code> call: the automation waits for completion and errors can propagate to the caller. Script parameters still use the generic HA action.</p><p>YAML import recognizes exact supported System action shapes. Additional data such as a custom logger or script variables remains in the generic HA action. Refresh behavior depends on integration support. Log messages are written when HA executes the automation; Info and Debug may be filtered by HA logging configuration.</p><p>References: <a href="https://www.home-assistant.io/integrations/system_log/" target="_blank" rel="noreferrer">HA system log</a>, <a href="https://www.home-assistant.io/integrations/script/" target="_blank" rel="noreferrer">HA scripts</a>, <a href="https://www.home-assistant.io/integrations/homeassistant/" target="_blank" rel="noreferrer">HA Core actions</a>.</p><h2 id="gear-icon-extend-branches" tabindex="-1">Gear icon: extend branches <a class="header-anchor" href="#gear-icon-extend-branches" aria-label="Permalink to &quot;Gear icon: extend branches&quot;">​</a></h2><p>As in the familiar ioBroker editor, the gear opens a small workspace. Attach <strong>else if</strong> clauses to the if container and optionally add <strong>else</strong>. Then connect conditions and actions in the main block.</p><ul><li>One branch generates <code>if</code>/<code>then</code>, optionally <code>else</code>.</li><li>Multiple branches generate <code>choose</code>; else becomes <code>default</code>.</li><li>HA runs the first matching branch, skipping any other matching branches.</li><li>Removed clauses detach connected blocks. Reconnect or remove them before exporting.</li><li>YAML import and JSON projects preserve branches. Older projects retain existing else actions.</li></ul><p>AND/OR/NOT has its own gear for 1–100 condition value inputs. Triggers and actions support chains. Sun, comparison and switching choices use dropdowns. Generic HA action data currently uses JSON; a visual data-field mutator is planned.</p><h2 id="connections-and-controls" tabindex="-1">Connections and controls <a class="header-anchor" href="#connections-and-controls" aria-label="Permalink to &quot;Connections and controls&quot;">​</a></h2><p>The category menu is dark and the block flyout is light. Values are green, triggers orange, conditions purple and actions blue. Category markers identify each block group; the selected category has an additional highlight.</p><ul><li><strong>Left output / right value input:</strong> Conditions produce Boolean values for the automation condition slot, if/else-if and AND/OR/NOT. Numbers produce Number values for thresholds and delays. Type checks reject incompatible connections.</li><li><strong>Previous / next:</strong> Triggers and actions each form their own statement chains and cannot be mixed.</li><li><strong>Statement cavity:</strong> Then/else slots accept action sequences. Conditions belong in value inputs.</li><li><strong>Shadow numbers:</strong> Thresholds and delays have editable defaults that can be replaced by number blocks. Removing a replacement restores the default. Log messages use String text blocks with editable shadows. Sensor and entity value blocks are not implemented yet.</li><li><strong>Context menu:</strong> Right-click or long-press for Blockly actions such as duplicate, comment, collapse, disable, delete and help. Help links to the documentation. Comments remain in JSON projects; YAML comment export is not implemented.</li><li><strong>Disable:</strong> Disabled actions, triggers and conditions are omitted from export. Required content remains required: missing triggers, empty if conditions or empty action branches prevent export.</li><li><strong>Trash:</strong> Delete blocks, open the trash and drag deleted blocks back to the workspace. History lasts for the current session. Undo/redo is also available.</li><li><strong>Insertion marker:</strong> Blockly previews the potential connection while dragging.</li></ul><p>Projects from version 0.1.4 and earlier are upgraded automatically. Old condition chains become AND groups preserving their YAML meaning. Existing supported YAML files remain importable.</p><h2 id="blockly-library-and-tracked-development-status" tabindex="-1">Blockly library and tracked development status <a class="header-anchor" href="#blockly-library-and-tracked-development-status" aria-label="Permalink to &quot;Blockly library and tracked development status&quot;">​</a></h2><p>We already use the original <strong>Blockly 13.3.0</strong> library rather than building a separate block engine. Blockly provides the workspace, category toolbox and flyouts, typed connections, shadow blocks, mutators, context menu, zoom, trash and insertion markers. HA block definitions, structural validation, project migration and the YAML generator are UGSo code. No ioBroker JavaScript is executed.</p><p>The <a href="https://docs.blockly.com/guides/get-started/workspace-anatomy/" target="_blank" rel="noreferrer">original workspace and block-parts documentation</a> and <a href="https://raspberrypifoundation.github.io/blockly-samples/" target="_blank" rel="noreferrer">Blockly examples</a> guide familiar interaction patterns. Library updates require connection, import/export and browser checks.</p><table tabindex="0"><thead><tr><th>Task</th><th>Status in 0.1.16 / next step</th></tr></thead><tbody><tr><td>Connection geometry and type checks</td><td>Boolean conditions and Number values use side connections; triggers/actions use separate statement chains</td></tr><tr><td>Extensible blocks</td><td>If, AND/OR/NOT, cases, objects and lists implemented; visual action-data fields planned</td></tr><tr><td>Default values</td><td>Shadow numbers and text blocks implemented; entity value blocks pending</td></tr><tr><td>Sensor values and attributes</td><td>Dedicated blocks pending; already usable through templates. Conversion blocks now provide type conversion</td></tr><tr><td>Editor controls</td><td>Context menu, help, disable, trash recovery, zoom and insertion markers available</td></tr><tr><td>Comments</td><td>Retained in projects; YAML comments and dedicated comment block pending</td></tr><tr><td>Menu and block colors</td><td>Dark category menu, light flyout and distinct group colors implemented</td></tr><tr><td>ioBroker categories</td><td>System, date/time, conversion, timeouts, objects and logic reviewed; HA execution differences documented</td></tr><tr><td>JSONata</td><td>Planned; evaluate native object/list access and an optional HA runtime adapter</td></tr><tr><td>Publishing and updates</td><td>Every new HA app starts in the shared repository with installable packaging; bump package and UI versions together</td></tr><tr><td>HA connection, catalog and plugins</td><td>Read-only entity integration and declarative block packages available; live action selection and package updates pending</td></tr></tbody></table><p>This page tracks implemented features and outstanding tasks together and is maintained with each extension.</p><h2 id="custom-blocks-implemented-and-roadmap" tabindex="-1">Custom blocks: implemented and roadmap <a class="header-anchor" href="#custom-blocks-implemented-and-roadmap" aria-label="Permalink to &quot;Custom blocks: implemented and roadmap&quot;">​</a></h2><p>Since 0.1.18 the HA form editor, Blockly preview, value/condition/action/trigger blocks, typed fields and value inputs, package import/export and embedded project definitions are available. <a href="./custom-blocks">Usage and limits</a>.</p><p>Embedding the original Blockly Developer Tools, dropdowns, images, variable fields, statement containers, mutators, dynamic inputs, package updates and uninstall remain planned.</p><h2 id="system-status-and-next-steps" tabindex="-1">System: status and next steps <a class="header-anchor" href="#system-status-and-next-steps" aria-label="Permalink to &quot;System: status and next steps&quot;">​</a></h2><p>Control, toggle, delay, generic actions, logging, script control, entity refresh and helper control are available. Entity selection is available since 0.1.17. Dedicated comment, state/attribute value, existence/availability and number/text helper blocks will follow progressively. ioBroker <code>ack</code>, adapter instances and datapoint creation have no direct HA counterpart.</p><p>The full <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/blocks_for_ha/docs/iobroker-comparison.en.md" target="_blank" rel="noreferrer">comparison and implementation status</a> is updated with every feature. Declarative block packages and a sample catalog are available since 0.1.18.</p><h2 id="validation-and-origin" tabindex="-1">Validation and origin <a class="header-anchor" href="#validation-and-origin" aria-label="Permalink to &quot;Validation and origin&quot;">​</a></h2><p>The editor validates supported structure. Entity IDs are searched or entered manually; installed actions and execution in real HA are not verified. Replace example entities and check actions in HA before use. The editor does not write HA system files.</p><p>Built with <a href="https://www.blockly.com/" target="_blank" rel="noreferrer">Blockly</a>. Original HA blocks, not an ioBroker fork. Our code and Blockly: Apache-2.0; YAML library: ISC. License texts are included.</p><h2 id="built-with-blockly" tabindex="-1">Built with Blockly <a class="header-anchor" href="#built-with-blockly" aria-label="Permalink to &quot;Built with Blockly&quot;">​</a></h2><p>Blockly is an open-source developer library from the Raspberry Pi Foundation, originally developed at Google. The app uses the unmodified official attribution badge since <strong>0.1.19</strong>, at 32px height with surrounding space and a link to Blockly. Both SVG variants are bundled locally. <a href="https://docs.blockly.com/guides/app-integration/attribution/" target="_blank" rel="noreferrer">Original attribution guidance</a>.</p><p><a class="blockly-attribution" href="https://www.blockly.com/" target="_blank" rel="noopener noreferrer"><img class="badge-light" src="`+t+'" alt="Built with Blockly" width="87" height="32"><img class="badge-dark" src="'+a+'" alt="Built with Blockly" width="87" height="32"></a></p><h2 id="home-assistant-sidebar" tabindex="-1">Home Assistant sidebar <a class="header-anchor" href="#home-assistant-sidebar" aria-label="Permalink to &quot;Home Assistant sidebar&quot;">​</a></h2><p>Since <strong>0.1.20</strong>, the sidebar entry uses the monochrome building-block icon <code>mdi:toy-brick-outline</code>. Update and restart the app, enable <strong>Show in sidebar</strong>, and reload Home Assistant if the previous icon persists. Native app configuration uses MDI icons; the colourful UGSo icon remains in the app store and editor. <a href="https://developers.home-assistant.io/docs/apps/configuration/" target="_blank" rel="noreferrer">HA configuration</a> · <a href="https://pictogrammers.com/library/mdi/icon/toy-brick-outline/" target="_blank" rel="noreferrer">Original icon</a>.</p><h2 id="workspace-search-and-keyboard-navigation" tabindex="-1">Workspace search and keyboard navigation <a class="header-anchor" href="#workspace-search-and-keyboard-navigation" aria-label="Permalink to &quot;Workspace search and keyboard navigation&quot;">​</a></h2><p>Since <strong>0.1.21</strong>, <strong>Suchen</strong> in the workspace toolbar finds blocks already placed on the canvas, including HA and custom blocks. The search at the bottom of the toolbox still finds available blocks to add. Search changes the view, not YAML or the saved project.</p><p>With focus in the workspace, <strong>Ctrl/Cmd+F</strong> opens search. <strong>Enter</strong> selects the next match, <strong>Shift+Enter</strong> the previous match, and <strong>Escape</strong> closes search and focuses the current block. Search buttons have German accessible labels, matching the editor UI.</p><p>The <strong>?</strong> button opens keyboard help. Blockly 13.3 provides navigation: Tab enters the workspace; arrow keys move through blocks and fields, Enter edits fields, T focuses the toolbox, and M picks up a block. Extra navigation shortcuts are enabled: Home/End within a block, Page Up/Down within a stack, Ctrl/Cmd+Home/End between first and last blocks, and Ctrl/Cmd+arrows to scroll. Text inputs and dialogs retain their normal editing behavior. Screen-reader behavior has not been independently verified.</p><p>Original sources: <a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/workspace-search" target="_blank" rel="noreferrer">workspace-search plugin</a>, <a href="https://docs.blockly.com/guides/configure/keyboard-nav/" target="_blank" rel="noreferrer">Blockly keyboard navigation</a>.</p><p>Since <strong>0.1.23</strong>, the introduction and automation settings use less vertical space: smaller heading and spacing, with 32-pixel project controls. This leaves more room for the workspace. The HA connection status and entity count are now displayed in the settings bar, including on narrow screens.</p><p>Since <strong>0.1.24</strong>, the arrow at the upper right of the HA output panel collapses it to the right. Blockly expands into the free space. The narrow <strong>HA-Ausgabe</strong> rail reopens the panel, with the state saved locally. On mobile, a compact row remains below the editor. Collapsing changes neither YAML nor projects.</p><p>Since <strong>0.1.28</strong>: <strong>States as JSON list</strong>, e.g. <code>[&quot;1_single&quot;,&quot;1_double&quot;]</code>; optional trigger IDs on every standard trigger; <strong>Triggered by ID</strong> as a native trigger condition (single ID or JSON list). Generic HA actions support <strong>Targets as JSON list</strong>, optional metadata and explicitly preserved empty data objects. Four-button automations with four <code>choose</code> branches can be fully imported.</p><p><strong>Single automation · HA editor</strong> output omits the top-level <code>id</code>. Trigger IDs remain. Projects and <strong>automations.yaml list</strong> output retain an existing automation ID.</p><p><a href="https://www.home-assistant.io/docs/automation/trigger/#trigger-id" target="_blank" rel="noreferrer">Home Assistant: Trigger IDs</a> · <a href="https://www.home-assistant.io/docs/scripts/conditions/#trigger-condition" target="_blank" rel="noreferrer">Trigger condition</a></p><p>Since <strong>0.1.29</strong>, the Blockly workspace fills the editor panel down to the legend. A taller YAML panel also expands the workspace; output remains collapsible.</p><p>Since <strong>0.1.30</strong>: enable <strong>Times as JSON list</strong> for several fixed times, e.g. <code>[&quot;10:00:00&quot;,&quot;13:00:00&quot;,&quot;19:00:00&quot;]</code>. <strong>Any change</strong> omits <code>to</code>; <strong>Entities as JSON list</strong> watches multiple entities. Without <code>to</code>, HA also reacts to attribute changes. Event triggers support e.g. <code>timer.finished</code> with an optional JSON data filter. Native time conditions preserve <code>before</code>/<code>after</code>: fixed times, after inclusive and before exclusive, including overnight windows. Equal bounds mean all day. Time helpers, time templates and weekday filters remain outside the supported import. The full pool-pump automation retains multiline timer templates and nested <code>choose</code> branches.</p><p><a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">Home Assistant: triggers</a> · <a href="https://www.home-assistant.io/docs/scripts/conditions/#time-condition" target="_blank" rel="noreferrer">Time condition</a></p><p>Since <strong>0.1.31</strong>, the new block supports native temperature.changed. Target (JSON): entity_id string or list. Threshold (JSON): type any, above, below, between or outside. any requires only type; above/below require value, between/outside value_min and value_max. Numbers: number plus unit_of_measurement (°C/°F). References: entity (sensor, number or input_number). Optional trigger ID. Other targets (area/device/label) remain unsupported. MQTT topics, qos/retain/evaluate_payload and multiline JSON/Jinja payloads are preserved.</p><p><a href="https://www.home-assistant.io/triggers/temperature.changed/" target="_blank" rel="noreferrer">Home Assistant: temperature.changed</a></p><p><strong>0.1.32:</strong> Calendars and response variables. <a href="./blocks">→</a></p><p><strong>0.1.33:</strong> Numeric triggers with hold duration. <a href="./blocks">→</a></p><p><strong>0.1.34:</strong> Multiple variables in one action. <a href="./blocks">→</a></p><p><strong>0.1.35:</strong> Delay as duration text or template. <a href="./blocks">→</a></p><p><strong>0.1.36:</strong> Dynamic HA action names. <a href="./blocks">→</a></p><p><strong>0.1.37:</strong> <a href="./blocks">Time pattern trigger</a>.</p><p><strong>0.1.38:</strong> <a href="./blocks">Dynamic target entities</a>.</p>',105)])])}const f=o(d,[["render",l]]);export{k as __pageData,f as default};
